CREATE     PROCEDURE [synapse_fo].[usp_Update_TRANSPORTATIONDOCUMENT]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:54
	Description: Update stored procedure for TRANSPORTATIONDOCUMENT from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[CARRIERCODE] = stg.[CARRIERCODE],
		tgt.[CARRIERTYPE] = stg.[CARRIERTYPE],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DOCUMENTDATETIME] = stg.[DOCUMENTDATETIME],
		tgt.[DOCUMENTDATETIMETZID] = stg.[DOCUMENTDATETIMETZID],
		tgt.[DOPRINTTRANSPORTATIONDOCUMENT] = stg.[DOPRINTTRANSPORTATIONDOCUMENT],
		tgt.[DROPOFFMODE_MX] = stg.[DROPOFFMODE_MX],
		tgt.[DROPOFFSPOT_MX] = stg.[DROPOFFSPOT_MX],
		tgt.[ECONOMICACTIVITYTYPE] = stg.[ECONOMICACTIVITYTYPE],
		tgt.[ENVIRONMENTALDAMAGEINSURANCEPOLICYNUM_MX] = stg.[ENVIRONMENTALDAMAGEINSURANCEPOLICYNUM_MX],
		tgt.[ENVIRONMENTALDAMAGEINSURANCEVENDOR_MX] = stg.[ENVIRONMENTALDAMAGEINSURANCEVENDOR_MX],
		tgt.[FileName] = stg.[FileName],
		tgt.[ISSUEDBY] = stg.[ISSUEDBY],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LINEID] = stg.[LINEID],
		tgt.[LOADEDADDRESSNAME] = stg.[LOADEDADDRESSNAME],
		tgt.[LOADEDDATETIME] = stg.[LOADEDDATETIME],
		tgt.[LOADEDDATETIMETZID] = stg.[LOADEDDATETIMETZID],
		tgt.[LOADEDPOSTALADDRESS] = stg.[LOADEDPOSTALADDRESS],
		tgt.[LSN] = stg.[LSN],
		tgt.[PACKAGEDANGERDEGREE] = stg.[PACKAGEDANGERDEGREE],
		tgt.[PACKAGEDESCRIPTION] = stg.[PACKAGEDESCRIPTION],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PICKUPMODE_MX] = stg.[PICKUPMODE_MX],
		tgt.[PICKUPSPOT_MX] = stg.[PICKUPSPOT_MX],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[SATPERMISSIONID_MX] = stg.[SATPERMISSIONID_MX],
		tgt.[SATPERMISSIONTYPE_MX] = stg.[SATPERMISSIONTYPE_MX],
		tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TRAVELDISTANCE_MX] = stg.[TRAVELDISTANCE_MX],
		tgt.[TRAVELTIME_MX] = stg.[TRAVELTIME_MX],
		tgt.[UNLOADEDADDRESSNAME] = stg.[UNLOADEDADDRESSNAME],
		tgt.[UNLOADEDDATETIME] = stg.[UNLOADEDDATETIME],
		tgt.[UNLOADEDDATETIMETZID] = stg.[UNLOADEDDATETIMETZID],
		tgt.[UNLOADEDPOSTALADDRESS] = stg.[UNLOADEDPOSTALADDRESS],
		tgt.[WEIGHTUNIT_MX] = stg.[WEIGHTUNIT_MX]
	 FROM [synapse_fo].[TRANSPORTATIONDOCUMENT] tgt
		INNER JOIN [staging_fo].[TRANSPORTATIONDOCUMENT] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
